    manifest = {
        "metadata": {
            "generated_at": datetime.now().isoformat(),
            "system_integrity": "verified"
        },
        "files": {}
    }

    for root, _, files in os.walk(root_dir):
        for file in files:
            if file.endswith(('.py', '.js', '.json', '.md')):
                file_path = os.path.join(root, file)
                try:
                    manifest["files"][file_path] = calculate_sha256(file_path)
                except Exception as e:
                    print(f"Error processing {file_path}: {e}")

    with open("checksum_manifest.json", "w") as f:
        json.dump(manifest, f, indent=4)
    return "checksum_manifest.json"

if __name__ == "__main__":
    # Thực thi quét tại thư mục hiện tại
    project_root = os.getcwd()
    output_file = generate_manifest(project_root)
    print(f"[SUCCESS] Manifest generated at: {output_file}")
